import { describe, expect, it } from "vitest"
import { COMMENT_FIELDS } from "../../src/vendor/meta-client/pages/constants.js"
import { normalizeComment, normalizePage, normalizePost } from "../../src/vendor/meta-client/pages/normalize.js"

describe("normalizeComment", () => {
  it("maps Graph field names onto the normalized shape", () => {
    expect(
      normalizeComment({
        id: "1_2",
        message: "Is this still in stock?",
        created_time: "2026-08-30T10:00:00+0000",
        from: { id: "u1", name: "A Person" },
        like_count: 3,
        comment_count: 1,
        is_hidden: false,
        can_comment: true,
        can_hide: true,
        permalink_url: "https://facebook.com/1_2",
      }),
    ).toEqual({
      id: "1_2",
      message: "Is this still in stock?",
      createdTime: "2026-08-30T10:00:00+0000",
      author: { id: "u1", name: "A Person" },
      likeCount: 3,
      replyCount: 1,
      hidden: false,
      canComment: true,
      canHide: true,
      permalink: "https://facebook.com/1_2",
    })
  })

  it("omits author entirely when `from` is absent", () => {
    // Graph omits `from` rather than nulling it when the token cannot see the
    // author. An `author: {}` would read as "known to be anonymous".
    const result = normalizeComment({ id: "1_2", message: "hi" })

    expect(result).not.toHaveProperty("author")
    expect(result.id).toBe("1_2")
  })

  it("keeps an id-only comment valid", () => {
    expect(normalizeComment({ id: "1_2" })).toEqual({ id: "1_2" })
  })

  it("carries the parent id when the comment is a reply", () => {
    expect(normalizeComment({ id: "1_3", parent: { id: "1_2" } }).parentId).toBe("1_2")
  })
})

describe("normalizePost", () => {
  it("defaults isPublished to true when Graph omits the field", () => {
    // Absent must not read as unpublished: mislabelling an organic post as an
    // ad post would misattribute every comment on it.
    expect(normalizePost({ id: "p1" }).isPublished).toBe(true)
  })

  it("preserves an explicit false", () => {
    expect(normalizePost({ id: "p1", is_published: false }).isPublished).toBe(false)
  })

  it("maps message, created_time and permalink_url", () => {
    expect(
      normalizePost({
        id: "p1",
        message: "New drop",
        created_time: "2026-08-01T00:00:00+0000",
        permalink_url: "https://facebook.com/p1",
        is_published: true,
      }),
    ).toEqual({
      id: "p1",
      message: "New drop",
      createdTime: "2026-08-01T00:00:00+0000",
      permalink: "https://facebook.com/p1",
      isPublished: true,
    })
  })
})

describe("normalizePage", () => {
  it("never carries an access token into the normalized shape", () => {
    const result = normalizePage({
      id: "pg1",
      name: "Shop",
      category: "Retail",
      tasks: ["MODERATE", "ANALYZE"],
      access_token: "SECRET-TOKEN",
    })

    expect(JSON.stringify(result)).not.toContain("SECRET-TOKEN")
    expect(result).toEqual({
      id: "pg1",
      name: "Shop",
      category: "Retail",
      tasks: ["MODERATE", "ANALYZE"],
    })
  })
})

